const s = $input.first().json;
const REQUIRED = ['myAddress', 'telegramChatId'];
// Stop early with a clear message if Settings still holds the template placeholders.
const unset = REQUIRED.filter(k => !String(s[k] ?? '').trim() || String(s[k]).includes('REPLACE_ME'));
if (unset.length) {
  throw new Error('Open the Settings node and fill in: ' + unset.join(', ') + '. They still contain REPLACE_ME placeholders.');
}

// Gmail search accepts "after:<unix seconds>", so we can look back an exact number of hours.
const hours = Number(s.lookbackHours) || 24;
const after = Math.floor((Date.now() - hours * 3600 * 1000) / 1000);
const query = ['in:inbox', '-from:me', `after:${after}`, String(s.extraQuery || '').trim()].filter(Boolean).join(' ');

return [{ json: { ...s, lookbackHours: hours, query } }];

// "Always Output Data" is on for Get Recent Emails, so an empty inbox arrives as one empty item.
const messages = $input.all().map(i => i.json).filter(m => m && m.id);

const emails = messages.map((m, idx) => {
  const headers = m.headers || {};
  const h = key => String(headers[key] || '').toLowerCase();
  const sender = (m.from && m.from.value && m.from.value[0]) || {};
  const fromAddr = String(sender.address || '').toLowerCase();
  const fromName = sender.name || fromAddr;
  // Newsletters and notifications get a shorter excerpt: the AI only needs to know what they are.
  const bulk =
    Boolean(headers['list-unsubscribe']) ||
    /(bulk|list)/.test(h('precedence')) ||
    /(no-?reply|do-?not-?reply|notifications?@|newsletter|mailer-daemon)/i.test(fromAddr);
  const body = String(m.text || '').replace(/\s+/g, ' ').trim().slice(0, bulk ? 400 : 1500);
  return {
    n: idx + 1,
    threadId: m.threadId,
    fromName,
    fromAddr,
    subject: m.subject || '(no subject)',
    unread: (m.labelIds || []).includes('UNREAD'),
    bulk,
    body,
  };
});

const prompt = emails
  .map(e => `#${e.n}${e.unread ? ' [unread]' : ''}${e.bulk ? ' [bulk/automated]' : ''}\nFrom: ${e.fromName} <${e.fromAddr}>\nSubject: ${e.subject}\n${e.body}`)
  .join('\n\n---\n\n');

return [{ json: { count: emails.length, emails, prompt } }];

const s = $('Check Settings').first().json;
const { emails } = $('Build Email List').first().json;
const ai = $input.first().json.output || {};
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const link = e => `https://mail.google.com/mail/u/${s.myAddress}/#all/${e.threadId}`;

const byN = new Map(emails.map(e => [e.n, e]));
const buckets = { needs_reply: [], important: [], fyi: [], ignore: [] };
const seen = new Set();
for (const it of ai.items || []) {
  const e = byN.get(Number(it.n));
  if (!e || seen.has(e.n)) continue;
  seen.add(e.n);
  (buckets[it.bucket] || buckets.fyi).push({ e, summary: it.summary || e.subject });
}
// Anything the AI left out still shows up, so no email slips through unseen.
for (const e of emails) if (!seen.has(e.n)) buckets.fyi.push({ e, summary: e.subject });

const row = ({ e, summary }) => `• <b>${esc(e.fromName)}</b>: ${esc(summary)} <a href="${link(e)}">open</a>`;
const lines = [`☀️ <b>Inbox digest, ${$now.toFormat('cccc d LLLL')}</b>`];
if (ai.overview) lines.push(esc(ai.overview));

const sections = [
  ['needs_reply', '✍️ <b>Needs your reply</b>'],
  ['important', '❗ <b>Important</b>'],
  ['fyi', '📄 <b>FYI</b>'],
];
for (const [key, title] of sections) {
  if (!buckets[key].length) continue;
  lines.push('', `${title} (${buckets[key].length})`);
  for (const x of buckets[key]) lines.push(row(x));
}
if (buckets.ignore.length) {
  lines.push('', `🗑️ ${buckets.ignore.length} newsletter${buckets.ignore.length === 1 ? '' : 's'}, promotions and notifications skipped.`);
}

// Telegram allows 4,096 characters per message, so split long messages on line breaks.
const chunks = [];
let cur = '';
for (const l of lines) {
  if (cur && (cur + '\n' + l).length > 3900) { chunks.push(cur); cur = l; }
  else cur = cur ? cur + '\n' + l : l;
}
if (cur.trim()) chunks.push(cur);
return chunks.map(text => ({ json: { text } }));
